create or replace function public.report_monthly_scorecard(p_from date default null, p_to date default null) returns jsonb language plpgsql stable security definer set search_path to 'public' as $fn$ declare v_from date := date_trunc('month', coalesce(p_from, (date_trunc('month', now() at time zone 'America/New_York') - interval '11 months')::date))::date; v_to date := coalesce(p_to, (now() at time zone 'America/New_York')::date); v jsonb; begin if not public.is_admin() then raise exception 'reports are office-only' using errcode = '42501'; end if; if v_to < v_from then raise exception 'report end is before its start' using errcode = '22023'; end if; with months as (select gs::date m from generate_series(v_from::timestamp, date_trunc('month', v_to::timestamp), interval '1 month') gs), live as (select * from public.jobs where coalesce(ghl_status, '') not in ('lost', 'abandoned')), comp as (select * from public.job_completion_dates()), fin as (select date_trunc('month', f.finalized_at at time zone 'America/New_York')::date m, f.seq, f.contract_amount - coalesce(p.contract_amount, 0) rev_delta, f.margin - coalesce(p.margin, 0) gp_delta from public.job_finalizations f left join public.job_finalizations p on p.job_id = f.job_id and p.seq = f.seq - 1 join live l on l.id = f.job_id), prov as (select date_trunc('month', coalesce((c.completed_at at time zone 'America/New_York')::date, l.contract_signed_date))::date m, jf.contract_amount rev, jf.margin gp, c.completed_at is not null by_completion, coalesce(jf.vendor_total, 0) > 0 has_costs from live l join public.job_stages s on s.key = l.stage and s.is_complete join public.job_financials jf on jf.job_id = l.id left join comp c on c.job_id = l.id where not exists (select 1 from public.job_finalizations f where f.job_id = l.id)), pay as (select date_trunc('month', payment_date at time zone 'America/New_York')::date m, amount from public.client_payments where payment_date is not null), rows as (select mo.m, (select coalesce(sum(contract_amount), 0) from live where date_trunc('month', contract_signed_date)::date = mo.m) booked, (select count(*) from live where date_trunc('month', contract_signed_date)::date = mo.m) booked_jobs, (select coalesce(sum(amount), 0) from pay where pay.m = mo.m) collected, (select count(*) from pay where pay.m = mo.m) collected_payments, (select coalesce(sum(l.contract_amount), 0) from comp c join live l on l.id = c.job_id where date_trunc('month', c.completed_at at time zone 'America/New_York')::date = mo.m) completed, (select count(*) from comp c join live l on l.id = c.job_id where date_trunc('month', c.completed_at at time zone 'America/New_York')::date = mo.m) completed_jobs, (select coalesce(sum(rev_delta), 0) from fin where fin.m = mo.m) finalized_revenue, (select coalesce(sum(gp_delta), 0) from fin where fin.m = mo.m) gp_finalized, (select count(*) from fin where fin.m = mo.m and fin.seq = 1) finalized_jobs, (select count(*) from fin where fin.m = mo.m and fin.seq > 1) refinalized_jobs, (select coalesce(sum(rev), 0) from prov where prov.m = mo.m and has_costs) provisional_revenue, (select coalesce(sum(gp), 0) from prov where prov.m = mo.m and has_costs) gp_provisional, (select count(*) from prov where prov.m = mo.m and has_costs) provisional_jobs, (select count(*) from prov where prov.m = mo.m and has_costs and not by_completion) provisional_by_signed, (select count(*) from prov where prov.m = mo.m and not has_costs) no_cost_jobs from months mo) select jsonb_build_object('from', v_from, 'to', v_to, 'generated_at', now(), 'months', (select jsonb_agg(to_jsonb(r) || jsonb_build_object('gp_total', r.gp_finalized + r.gp_provisional, 'gp_pct', case when r.finalized_revenue + r.provisional_revenue > 0 then round((r.gp_finalized + r.gp_provisional) / (r.finalized_revenue + r.provisional_revenue), 4) end) order by r.m) from rows r), 'coverage', (select jsonb_build_object('jobs_live', (select count(*) from live), 'jobs_with_signed_date', (select count(*) from live where contract_signed_date is not null), 'complete_stage_jobs', (select count(*) from live l join public.job_stages s on s.key = l.stage and s.is_complete), 'complete_with_completion_date', (select count(*) from comp c join live l on l.id = c.job_id), 'finalized_jobs', (select count(distinct f.job_id) from public.job_finalizations f join live l on l.id = f.job_id), 'provisional_by_completion', (select count(*) from prov where has_costs and by_completion), 'provisional_by_signed', (select count(*) from prov where has_costs and not by_completion and m is not null), 'provisional_undated', (select count(*) from prov where has_costs and m is null), 'provisional_undated_revenue', (select coalesce(sum(rev), 0) from prov where has_costs and m is null), 'provisional_undated_gp', (select coalesce(sum(gp), 0) from prov where has_costs and m is null), 'complete_no_costs', (select count(*) from prov where not has_costs), 'complete_no_costs_revenue', (select coalesce(sum(rev), 0) from prov where not has_costs), 'payments_undated', (select count(*) from public.client_payments where payment_date is null), 'stage_log_since', (select min(changed_at) from public.job_stage_events)))) into v; return v; end $fn$;;
